#!/bin/bash
# Swap USDC → MON (reverse direction)
# USDC = currency1, MON(native) = currency0
# zeroForOne = false (swapping currency1 → currency0)
# Note: no --value since input is ERC20 not native MON

USDC_AMOUNT=220924

cast send 0x1B1Fee89A381E595Fe6536b99Ba91F3E16e9601a \
  --legacy \
  --gas-limit 2000000 \
  --rpc-url https://rpc-mainnet.monadinfra.com/rpc/sdI8stf4y6BdOAx4AFcJn7xGRyPtkJ8E \
  --private-key $DEPLOYER_PRIVATE_KEY \
  "swap(address,address,uint256,uint256,uint256,(address,address,address,uint256,bytes),address)" \
  0x754704Bc059F8C67012fEd69BC8A327a5aafb603 \
  0x3bd359C1119dA7Da1D913D1C4D2B7c461115433A \
  $USDC_AMOUNT \
  0 \
  99999999999 \
  "(0x1a2Aa87b0e9F5e313DD445bB058fAabfb1f645a0,0x754704Bc059F8C67012fEd69BC8A327a5aafb603,0x3bd359C1119dA7Da1D913D1C4D2B7c461115433A,$USDC_AMOUNT,)" \
  0x0000000000000000000000000000000000000000
